def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    bg = background(g)
    emit(g.copy(), "Initial grid: bands of 8 starting at the left edge; one spans the full width (reference).")
    comps = components(g != bg, diagonal=True)

    def profile(cells):
        cols = {}
        for y, x in cells:
            cols.setdefault(x, set()).add(y)
        return cols

    def tokens(cols, xs):
        t = []
        for a, b in zip(xs, xs[1:]):
            m = min(cols[a])
            t.append(tuple(sorted(y - m for y in cols[b])))
        return t

    ref = None
    for c in comps:
        if max(x for _, x in c) == W - 1:
            if ref is None or len(c) > len(ref):
                ref = c
    if ref is None:
        emit(g, "No reference band found; unchanged.")
        return g
    rcols = profile(ref)
    rxs = sorted(rcols)
    rt = tokens(rcols, rxs)

    out = g.copy()
    for c in comps:
        if c is ref:
            continue
        cols = profile(c)
        xs = sorted(cols)
        if xs[-1] >= W - 1:
            continue
        bt = tokens(cols, xs)
        start = None
        for L in range(len(bt), 0, -1):
            suf = bt[-L:]
            for i in range(len(rt) - L + 1):
                if rt[i:i + L] == suf:
                    start = i + L
                    break
            if start is not None:
                break
        if start is None:
            start = 0
        prev = cols[xs[-1]]
        k = start
        last = rt[-1] if rt else (0,)
        for x in range(xs[-1] + 1, W):
            tok = rt[k] if k < len(rt) else last
            k += 1
            m = min(prev)
            rows = set(m + d for d in tok)
            for y in rows:
                if 0 <= y < H and out[y, x] == bg:
                    out[y, x] = 1
            prev = rows
        emit(out.copy(), f"Extended the band ending at column {xs[-1]} to the right edge in colour 1, following the reference shape.")
    emit(out, "Final grid.")
    return out
